/* ---------------- raw syscalls ---------------- */

#define SYS_READ 0
#define SYS_WRITE 1
#define SYS_OPEN 2
#define SYS_CLOSE 3
#define SYS_LSEEK 8
#define SYS_TIME 201
#define SYS_RENAME 38
#define SYS_MKDIR 39
#define SYS_FCHMOD 94

int errno;

static long raw_syscall(long n, long a0, long a1, long a2)
{
    register long r_v0 __asm__("$2") = n;
    register long r_a0 __asm__("$4") = a0;
    register long r_a1 __asm__("$5") = a1;
    register long r_a2 __asm__("$6") = a2;
    __asm__ volatile("syscall"
                     : "+r"(r_v0)
                     : "r"(r_a0), "r"(r_a1), "r"(r_a2)
                     : "memory");
    return r_v0;
}

long read(int fd, void *buf, size_t count)
{
    long r = raw_syscall(SYS_READ, fd, (long)buf, (long)count);
    if (r < 0) errno = -r > 0 ? -r : 5;
    return r;
}

long write(int fd, const void *buf, size_t count)
{
    long r = raw_syscall(SYS_WRITE, fd, (long)buf, (long)count);
    if (r < 0) errno = 5;
    return r;
}

int close(int fd)
{
    long r = raw_syscall(SYS_CLOSE, fd, 0, 0);
    if (r < 0) { errno = 9; return -1; }
    return 0;
}

long lseek(int fd, long offset, int whence)
{
    long r = raw_syscall(SYS_LSEEK, fd, offset, whence);
    if (r < 0) { errno = 22; return -1; }
    return r;
}

int open(const char *pathname, int flags, ...)
{
    long r = raw_syscall(SYS_OPEN, (long)pathname, flags, 0644);
    if (r < 0) { errno = 2; return -1; }
    return (int)r;
}

int creat(const char *pathname, int mode)
{
    long r = raw_syscall(SYS_OPEN, (long)pathname,
                         O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (r < 0) { errno = 2; return -1; }
    return (int)r;
}

int mkdir(const char *pathname, unsigned int mode)
{
    long r = raw_syscall(SYS_MKDIR, (long)pathname, mode, 0);
    if (r < 0) { errno = 2; return -1; }
