static char *strtok_save;

char *strtok(char *str, const char *delim)
{
    char *p;
    if (str) strtok_save = str;
    if (!strtok_save) return 0;
    strtok_save += strspn(strtok_save, delim);
    if (!*strtok_save) { strtok_save = 0; return 0; }
    p = strtok_save;
    p += strcspn(p, delim);
    if (*p) {
        *p = '\0';
        strtok_save = p + 1;
    } else {
        strtok_save = 0;
    }
    return p;
}

