/* ---------------- malloc ---------------- */

#define HEAP_SIZE (24 * 1024 * 1024)

static unsigned char heap_area[HEAP_SIZE];

typedef struct mhdr {
    size_t size;
    struct mhdr *next;
    int free;
} mhdr;

static mhdr *heap_head;
static int heap_inited;

static void heap_init(void)
{
    heap_head = (mhdr *)heap_area;
    heap_head->size = HEAP_SIZE - sizeof(mhdr);
    heap_head->next = 0;
    heap_head->free = 1;
    heap_inited = 1;
}

static size_t align8(size_t n) { return (n + 7) & ~(size_t)7; }

void *malloc(size_t size)
{
    mhdr *h;
    if (!size) size = 1;
    if (!heap_inited) heap_init();
    size = align8(size);
    for (h = heap_head; h; h = h->next) {
        if (h->free && h->size >= size) {
            if (h->size >= size + sizeof(mhdr) + 8) {
                mhdr *n2 = (mhdr *)((unsigned char *)(h + 1) + size);
                n2->size = h->size - size - sizeof(mhdr);
                n2->next = h->next;
                n2->free = 1;
                h->size = size;
                h->next = n2;
            }
            h->free = 0;
            return (void *)(h + 1);
        }
    }
    return 0;
}

void free(void *ptr)
{
    mhdr *h;
    if (!ptr) return;
    h = ((mhdr *)ptr) - 1;
    h->free = 1;
    /* coalesce forward */
    for (h = heap_head; h && h->next; ) {
        if (h->free && h->next->free &&
            (unsigned char *)(h + 1) + h->size ==
                (unsigned char *)h->next) {
            h->size += sizeof(mhdr) + h->next->size;
            h->next = h->next->next;
        } else {
            h = h->next;
        }
    }
}

void *calloc(size_t nmemb, size_t size)
{
    size_t total = nmemb * size;
    void *p = malloc(total);
    if (p) memset(p, 0, total);
    return p;
}

void *realloc(void *ptr, size_t size)
{
    mhdr *h;
    void *n2;
    if (!ptr) return malloc(size);
    if (!size) { free(ptr); return malloc(1); }
    h = ((mhdr *)ptr) - 1;
    if (h->size >= align8(size)) return ptr;
    n2 = malloc(size);
    if (n2) {
        memcpy(n2, ptr, h->size);
        free(ptr);
    }
    return n2;
}

char *strdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = (char *)malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}

