static int digitval(int c, int base, int *out)
{
    int v;
    if (c >= '0' && c <= '9') v = c - '0';
    else if (c >= 'a' && c <= 'z') v = c - 'a' + 10;
    else if (c >= 'A' && c <= 'Z') v = c - 'A' + 10;
    else return 0;
    if (v >= base) return 0;
    *out = v;
    return 1;
}

long strtol(const char *nptr, char **endptr, int base)
{
    const char *s = nptr;
    unsigned long acc = 0;
    int neg = 0, any = 0, v;
    while (isspace((unsigned char)*s)) s++;
    if (*s == '-') { neg = 1; s++; }
    else if (*s == '+') s++;
    if (base == 0) {
        if (*s == '0' && (s[1] == 'x' || s[1] == 'X')) base = 16;
        else if (*s == '0') base = 8;
        else base = 10;
    }
    if (base == 16 && *s == '0' && (s[1] == 'x' || s[1] == 'X')) s += 2;
    while (digitval((unsigned char)*s, base, &v)) {
        acc = acc * (unsigned long)base + (unsigned long)v;
        any = 1;
        s++;
    }
    if (endptr) *endptr = (char *)(any ? s : nptr);
    if (neg) return -(long)acc;
    return (long)acc;
}

