        else if (*s == '0') base = 8;
        else base = 10;
    }
    if (base == 16 && *s == '0' && (s[1] == 'x' || s[1] == 'X')) s += 2;
    while (digitval((unsigned char)*s, base, &v)) {
        acc = acc * (unsigned long)base + (unsigned long)v;
        any = 1;
        s++;
    }
    if (endptr) *endptr = (char *)(any ? s : nptr);
