static unsigned long rand_state = 1;

int rand(void)
{
    rand_state = rand_state * 1103515245UL + 12345UL;
    return (int)((rand_state >> 16) & 0x7fff);
}

void srand(unsigned int seed)
{
    rand_state = seed ? seed : 1;
}

void *bsearch(const void *key, const void *base, size_t nmemb, size_t size,
              int (*compar)(const void *, const void *))
{
    size_t lo = 0, hi = nmemb;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        const void *p = (const char *)base + mid * size;
        int c = compar(key, p);
        if (c < 0) hi = mid;
        else if (c > 0) lo = mid + 1;
        else return (void *)p;
    }
    return 0;
}

static void swapb(char *a, char *b, size_t n)
{
    while (n--) { char t = *a; *a++ = *b; *b++ = t; }
}

void qsort(void *base, size_t nmemb, size_t size,
           int (*compar)(const void *, const void *))
{
    char *b = (char *)base;
    size_t i, last;
    if (nmemb < 2 || size == 0) return;
    /* simple quicksort with middle pivot */
    swapb(b, b + (nmemb / 2) * size, size);
    last = 0;
    for (i = 1; i < nmemb; i++) {
        if (compar(b + i * size, b) < 0) {
            last++;
            swapb(b + last * size, b + i * size, size);
        }
    }
    swapb(b, b + last * size, size);
    qsort(b, last, size, compar);
    qsort(b + (last + 1) * size, nmemb - last - 1, size, compar);
}"}

