{"content":"/* stdio implementation over raw syscalls. Pure 32-bit C; float formatting
 * uses double arithmetic (served by our own soft-float helpers). */

#include <stddef.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>

struct MY_FILE {
    int fd;
    int eof;
    int err;
    int has_pb;
    int pushback;
};

static FILE stdin_obj = { 0, 0, 0, 0, 0 };
static FILE stdout_obj = { 1, 0, 0, 0, 0 };
static FILE stderr_obj = { 2, 0, 0, 0, 0 };

FILE *stdin = &stdin_obj;
FILE *stdout = &stdout_obj;
FILE *stderr = &stderr_obj;

#define MAX_FILES 24
static FILE file_pool[MAX_FILES];
static int file_used[MAX_FILES];

int fileno(FILE *stream) { return stream->fd; }

FILE *fopen(const char *path, const char *mode)
{
    int flags = 0, plus = 0, i;
    const char *m = mode;
    char main_c = 0;
    while (*m) {
        if (*m == 'r' || *m == 'w' || *m == 'a') main_c = *m;
        else if (*m == '+') plus = 1;
        m++;
    }
    if (main_c == 'r') flags = plus ? O_RDWR : O_RDONLY;
    else if (main_c == 'w') flags = O_CREAT | O_TRUNC | (plus ? O_RDWR : O_WRONLY);
    else if (main_c == 'a') flags = O_CREAT | O_APPEND | (plus ? O_RDWR : O_WRONLY);
    else return 0;
    {
        long fd = raw_syscall(2, (long)path, flags, 0644);
        if (fd < 0 || fd > 100000) return 0;
        for (i = 0; i < MAX_FILES; i++) {
            if (!file_used[i]) {
                file_used[i] = 1;
                file_pool[i].fd = (int)fd;
                file_pool[i].eof = 0;
                file_pool[i].err = 0;
                file_pool[i].has_pb = 0;
                file_pool[i].pushback = 0;
                return &file_pool[i];
            }
        }
        raw_syscall(3, fd, 0, 0);
        return 0;
    }
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *stream)
{
    size_t total, got = 0;
    if (size == 0 || nmemb == 0) return 0;
    total = size * nmemb;
    while (got < total) {
        long r;
        if (stream->has_pb) {
            ((unsigned char *)ptr)[got++] = (unsigned char)stream->pushback;
            stream->has_pb = 0;
            continue;
        }
        r = raw_syscall(0, stream->fd,
                        (long)((unsigned char *)ptr + got), total - got);
        if (r <= 0) {
            if (r == 0) stream->eof = 1;
            else stream->err = 1;
            break;
        }
        got += (size_t)r;
    }
    return got / size;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *stream)
{
    size_t total, put = 0;
    if (size == 0 || nmemb == 0) return 0;
    total = size * nmemb;
    while (put < total) {
        long r = raw_syscall(1, stream->fd,
                             (long)((const unsigned char *)ptr + put),
                             total - put);
        if (r <= 0) { stream->err = 1; break; }
        put += (size_t)r;
    }
    return put / size;
}

int fseek(FILE *stream, long offset, int whence)
{
    long r = raw_syscall(8, stream->fd, offset, whence);
    if (r < 0) { stream->err = 1; return -1; }
    stream->eof = 0;
    stream->has_pb = 0;
    return 0;
}

long ftell(FILE *stream)
{
    long r = raw_syscall(8, stream->fd, 0, SEEK_CUR);
    if (r < 0) { stream->err = 1; return -1; }
    return r;
}

int fclose(FILE *stream)
{
    int i;
    if (stream == stdin || stream == stdout || stream == stderr) return 0;
    raw_syscall(3, stream->fd, 0, 0);
    for (i = 0; i < MAX_FILES; i++) {
        if (&file_pool[i] == stream) { file_used[i] = 0; break; }
    }
    return 0;
}

int fflush(FILE *stream)
{
    (void)stream;
    return 0;
}

int feof(FILE *stream) { return stream->eof; }
int ferror(FILE *stream) { return stream->err; }

int fgetc(FILE *stream)
{
    unsigned char c;
    if (stream->has_pb) {
        stream->has_pb = 0;
        return stream->pushback;
    }
    if (fread(&c, 1, 1, stream) != 1) return EOF;
    return c;
}

char *fgets(char *s, int size, FILE *stream)
{
    int i = 0, c;
    if (size <= 1) return 0;
    while (i < size - 1) {
        c = fgetc(stream);
        if (c == EOF) break;
        s[i++] = (char)c;
        if (c == '\n') break;
    }
    if (i == 0) return 0;
    s[i] = '\0';
