            }
            /* length */
            if (*fmt == 'h') { fmt++; if (*fmt == 'h') fmt++; }
            else if (*fmt == 'l') { fmt++; longn = 1; if (*fmt == 'l') fmt++; }
            else if (*fmt == 'j' || *fmt == 'z' || *fmt == 't' || *fmt == 'L') fmt++;
            (void)longn; (void)haves;
            switch (*fmt) {
            case 'd': case 'i':
                sval = va_arg(ap, int);
                if (sval < 0) fmt_int(&o, (unsigned long)(-sval), 1, 10, 0, width, prec, flags);
                else fmt_int(&o, (unsigned long)sval, 0, 10, 0, width, prec, flags);
                break;
            case 'u':
                uval = va_arg(ap, unsigned int);
                fmt_int(&o, uval, 0, 10, 0, width, prec, flags);
                break;
            case 'o':
                uval = va_arg(ap, unsigned int);
                fmt_int(&o, uval, 0, 8, 0, width, prec, flags);
                break;
            case 'x': case 'X':
                uval = va_arg(ap, unsigned int);
                fmt_int(&o, uval, 0, 16, *fmt == 'X', width, prec, flags);
                break;
            case 'c': {
                int c = va_arg(ap, int);
                int pad = width > 1 ? width - 1 : 0, i;
                if (!(flags & 1)) for (i = 0; i < pad; i++) sout_put(&o, ' ');
                sout_put(&o, (char)c);
                if (flags & 1) for (i = 0; i < pad; i++) sout_put(&o, ' ');
                break;
            }
            case 's':
                svalp = va_arg(ap, const char *);
                if (!svalp) svalp = "(null)";
                {
                    size_t sl = strlen(svalp);
                    int pad, i;
                    if (prec >= 0 && sl > (size_t)prec) sl = (size_t)prec;
                    pad = width > (int)sl ? width - (int)sl : 0;
                    if (!(flags & 1)) for (i = 0; i < pad; i++) sout_put(&o, ' ');
                    sout_str(&o, svalp, sl);
                    if (flags & 1) for (i = 0; i < pad; i++) sout_put(&o, ' ');
                }
                break;
            case 'p':
                uval = (unsigned long)va_arg(ap, void *);
                {
                    char tmp[16];
                    int i, n = 0;
                    unsigned long v = uval;
                    if (v == 0) tmp[n++] = '0';
                    else { while (v) { tmp[n++] = "REDACTED00000000000000000245"[v & 0xf]; v >>= 4; } }
                    {
                        int tot = n + 2, pad = width > tot ? width - tot : 0, k;
                        if (!(flags & 1)) for (k = 0; k < pad; k++) sout_put(&o, ' ');
                        sout_put(&o, '0'); sout_put(&o, 'x');
                        for (i = n - 1; i >= 0; i--) sout_put(&o, tmp[i]);
                        if (flags & 1) for (k = 0; k < pad; k++) sout_put(&o, ' ');
                    }
                }
                break;
            case 'n': {
                int *ip = va_arg(ap, int *);
                *ip = o.total;
                break;
            }
            case 'f': case 'F': {
                char fb[96];
                sout fo;
                int flen, pad, i;
                dval = va_arg(ap, double);
                fo.buf = fb; fo.cap = sizeof(fb); fo.len = 0; fo.total = 0;
                fmt_double(&fo, dval, prec, flags & (2 | 4 | 8));
                if (fo.len >= sizeof(fb)) fo.len = sizeof(fb) - 1;
                flen = (int)fo.len;
                pad = width > flen ? width - flen : 0;
                if (!(flags & 1)) {
                    char pc = (flags & 16) ? '0' : ' ';
                    if (pc == '0' && flen && (fb[0] == '-' || fb[0] == '+' || fb[0] == ' ')) {
                        sout_put(&o, fb[0]);
                        for (i = 0; i < pad; i++) sout_put(&o, '0');
                        sout_str(&o, fb + 1, (size_t)(flen - 1));
                    } else {
                        for (i = 0; i < pad; i++) sout_put(&o, pc);
                        sout_str(&o, fb, (size_t)flen);
                    }
                } else {
                    sout_str(&o, fb, (size_t)flen);
                    for (i = 0; i < pad; i++) sout_put(&o, ' ');
                }
                break;
            }
            case 'e': case 'E': {
                /* scientific: normalize then reuse %f */
                char fb[96];
                sout fo;
                int flen, pad, i, exp = 0;
                char ec = *fmt == 'E' ? 'E' : 'e';
                dval = va_arg(ap, double);
                {
                    int neg = 0, cls = dbl_class(dval, &neg);
                    if (cls) {
                        fmt_double(&o, dval, prec, flags & (2 | 4 | 8));
                        break;
                    }
                    if (neg) dval = -dval;
                    if (dval != 0.0) {
                        while (dval >= 10.0) { dval /= 10.0; exp++; }
                        while (dval < 1.0) { dval *= 10.0; exp--; }
                    }
                    if (neg) { sout_put(&o, '-'); }
                    else if (flags & 2) sout_put(&o, '+');
                    else if (flags & 4) sout_put(&o, ' ');
                    fo.buf = fb; fo.cap = sizeof(fb); fo.len = 0; fo.total = 0;
                    fmt_double(&fo, dval, prec < 0 ? 6 : prec, 0);
                    if (fo.len >= sizeof(fb)) fo.len = sizeof(fb) - 1;
                    sout_str(&o, fb, fo.len);
                    sout_put(&o, ec);
                    sout_put(&o, exp < 0 ? '-' : '+');
                    if (exp < 0) exp = -exp;
                    if (exp < 10) sout_put(&o, '0');
                    {
                        char eb[16];
                        int en = 0;
                        if (exp == 0) eb[en++] = '0';
                        while (exp) { eb[en++] = (char)('0' + exp % 10); exp /= 10; }
                        while (en--) sout_put(&o, eb[en]);
                    }
                    flen = 0; pad = 0; i = 0; done = 1;
                }
                (void)flen; (void)pad; (void)i;
                break;
            }
            case 'g': case 'G':
                /* simple fallback: same as %f */
                dval = va_arg(ap, double);
                fmt_double(&o, dval, prec, flags & (2 | 4 | 8));
                break;
            case '%':
                sout_put(&o, '%');
                break;
            default:
                sout_put(&o, '%');
                sout_put(&o, *fmt);
                break;
            }
            fmt++;
        }
    }
    if (o.cap > 0) {
        if (o.len >= o.cap) o.buf[o.cap - 1] = '\0';
        else o.buf[o.len] = '\0';
    }
    return o.total;
}

int vsprintf(char *str, const char *format, va_list ap)
{
    return vsnprintf(str, 0x7fffffff, format, ap);
}

int sprintf(char *str, const char *format, ...)
{
    va_list ap;
    int r;
    va_start(ap, format);
    r = vsnprintf(str, 0x7fffffff, format, ap);
    va_end(ap);
    return r;
}

int snprintf(char *str, size_t size, const char *format, ...)
{
    va_list ap;
    int r;
    va_start(ap, format);
    r = vsnprintf(str, size, format, ap);
    va_end(ap);
    return r;
}

static int vout_write(FILE *f, const char *format, va_list ap)
{
    char small[2048];
    char *big = 0;
    int n, w;
    va_list ap2;
    va_copy(ap2, ap);
    n = vsnprintf(small, sizeof(small), format, ap);
    if (n < 0) { va_end(ap2); return -1; }
    if (n < (int)sizeof(small)) {
        w = (int)fwrite(small, 1, (size_t)n, f);
    } else {
        big = (char *)malloc((size_t)n + 1);
        if (!big) { va_end(ap2); return -1; }
        vsnprintf(big, (size_t)n + 1, format, ap2);
        w = (int)fwrite(big, 1, (size_t)n, f);
        free(big);
    }
    va_end(ap2);
    return w == n ? n : -1;
}

int vprintf(const char *format, va_list ap)
{
    return vout_write(stdout, format, ap);
}

int vfprintf(FILE *stream, const char *format, va_list ap)
{
    return vout_write(stream, format, ap);
}

int printf(const char *format, ...)
{
    va_list ap;
    int r;
    va_start(ap, format);
    r = vout_write(stdout, format, ap);
    va_end(ap);
    return r;
}

int fprintf(FILE *stream, const char *format, ...)
{
    va_list ap;
    int r;
    va_start(ap, format);
    r = vout_write(stream, format, ap);
    va_end(ap);
    return r;
}

/* ---------------- scanf core ---------------- */

static int scan_getc(FILE *f, int *eof)
{
    int c = fgetc(f);
    if (c == EOF) *eof = 1;
    return c;
}

static int scan_isspace(int c) { return isspace(c); }

static int scan_digits(FILE *f, int base, unsigned long *out, int width,
                       int *eof, int *ndig)
{
    unsigned long v = 0;
    int n = 0, c, d;
    *ndig = 0;
    for (;;) {
        if (width == 0) break;
        c = scan_getc(f, eof);
        if (c == EOF) break;
        d = -1;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'z') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'Z') d = c - 'A' + 10;
        if (d < 0 || d >= base) { ungetc(c, f); break; }
        v = v * (unsigned long)base + (unsigned long)d;
        n++;
        if (width > 0) width--;
    }
    *out = v;
    *ndig = n;
    return n;
}

static int vfscanf_impl(FILE *f, const char *fmt, va_list ap)
{
    int assigned = 0, eof = 0, nchars = 0;
    while (*fmt && !eof) {
        if (scan_isspace((unsigned char)*fmt)) {
            int c;
            fmt++;
            while (scan_isspace((unsigned char)*fmt)) fmt++;
            do { c = scan_getc(f, &eof); nchars++; } while (!eof && scan_isspace(c));
            if (!eof) ungetc(c, f);
            else nchars--;
            continue;
        }
        if (*fmt != '%') {
            int c = scan_getc(f, &eof);
            nchars++;
            if (eof || c != (unsigned char)*fmt) break;
            fmt++;
            continue;
        }
        fmt++;
        {
            int suppress = 0, width = -1, islong = 0, isshort = 0;
            if (*fmt == '*') { suppress = 1; fmt++; }
            if (*fmt >= '0' && *fmt <= '9') {
                width = 0;
                while (*fmt >= '0' && *fmt <= '9') width = width * 10 + (*fmt++ - '0');
            }
            if (*fmt == 'h') { isshort = 1; fmt++; if (*fmt == 'h') fmt++; }
            else if (*fmt == 'l') { fmt++; islong = 1; if (*fmt == 'l') fmt++; }
            else if (*fmt == 'j' || *fmt == 'z' || *fmt == 't' || *fmt == 'L') fmt++;
            if (*fmt == '%') {
                int c = scan_getc(f, &eof);
                nchars++;
                if (eof || c != '%') break;
                fmt++;
                continue;
            } else if (*fmt == 'n') {
                int *ip = suppress ? 0 : va_arg(ap, int *);
                if (ip) *ip = nchars;
                fmt++;
                continue;
            } else if (*fmt == 'c') {
                char *sp = suppress ? 0 : va_arg(ap, char *);
                int n = width < 0 ? 1 : width, i;
                for (i = 0; i < n; i++) {
                    int c = scan_getc(f, &eof);
                    if (eof) break;
                    nchars++;
                    if (sp) sp[i] = (char)c;
                }
                if (eof && (width < 0 || nchars == 0)) break;
                if (!suppress && n > 0) assigned++;
                fmt++;
                continue;
            } else if (*fmt == 's') {
                char *sp = suppress ? 0 : va_arg(ap, char *);
                int c, n = 0;
                do { c = scan_getc(f, &eof); if (!eof) nchars++; } while (!eof && scan_isspace(c));
                if (eof) break;
                for (;;) {
                    if (width >= 0 && n >= width) { ungetc(c, f); nchars--; break; }
                    if (scan_isspace(c)) { ungetc(c, f); nchars--; break; }
                    if (sp) sp[n] = (char)c;
                    n++;
                    c = scan_getc(f, &eof);
                    if (eof) break;
                    nchars++;
                }
                if (n == 0) break;
                if (sp) sp[n] = '\0';
                if (!suppress) assigned++;
                fmt++;
                continue;
            } else if (*fmt == '[') {
                char *sp = suppress ? 0 : va_arg(ap, char *);
                char set[256];
                int negate = 0, n = 0, c;
                fmt++;
                memset(set, 0, sizeof(set));
                if (*fmt == '^') { negate = 1; fmt++; }
                if (*fmt == ']') { set[']'] = 1; fmt++; }
                while (*fmt && *fmt != ']') {
                    if (fmt[1] == '-' && fmt[2] && fmt[2] != ']') {
                        int a = (unsigned char)fmt[0], b = (unsigned char)fmt[2], k;
                        for (k = a; k <= b; k++) set[k] = 1;
                        fmt += 3;
                    } else {
                        set[(unsigned char)*fmt] = 1;
                        fmt++;
                    }
                }
                if (*fmt == ']') fmt++;
                c = scan_getc(f, &eof);
                if (!eof) nchars++;
                for (;;) {
                    int hit;
                    if (eof) break;
                    hit = set[c] ? 1 : 0;
                    if (negate) hit = !hit;
                    if (!hit) { ungetc(c, f); nchars--; break; }
                    if (width >= 0 && n >= width) { ungetc(c, f); nchars--; break; }
                    if (sp) sp[n] = (char)c;
                    n++;
                    c = scan_getc(f, &eof);
                    if (!eof) nchars++;
                }
                if (n == 0) break;
                if (sp) sp[n] = '\0';
                if (!suppress) assigned++;
                continue;
            } else if (*fmt == 'd' || *fmt == 'u' || *fmt == 'i' ||
                       *fmt == 'o' || *fmt == 'x' || *fmt == 'X') {
                int base = 10, neg = 0, c;
                unsigned long v = 0;
                int nd = 0, w = width;
                do { c = scan_getc(f, &eof); if (!eof) nchars++; } while (!eof && scan_isspace(c));
                if (eof) break;
                if (c == '+' || c == '-') {
                    neg = (c == '-');
                    if (w == 0) { ungetc(c, f); nchars--; break; }
                    if (w > 0) w--;
                    c = scan_getc(f, &eof);
                    if (!eof) nchars++;
                    if (eof) break;
                }
                if (*fmt == 'i') {
                    if (c == '0') {
                        int c2 = scan_getc(f, &eof);
                        if (!eof) nchars++;
                        if (!eof && (c2 == 'x' || c2 == 'X')) {
                            base = 16;
                            if (w > 0) w -= 2;
                            c = scan_getc(f, &eof);
                            if (!eof) nchars++;
                        } else {
                            base = 8;
                            c = c2;
                            if (!eof) { ungetc(c, f); nchars--; }
                            c = '0';
                            /* re-read the 0 as first digit */
                        }
                    } else base = 10;
                } else if (*fmt == 'o') base = 8;
                else if (*fmt == 'x' || *fmt == 'X') base = 16;
                if (base == 16 && c == '0') {
                    int c2 = scan_getc(f, &eof);
                    if (!eof) nchars++;
                    if (!eof && (c2 == 'x' || c2 == 'X')) {
                        if (w > 0) w -= 2;
                        c = scan_getc(f, &eof);
                        if (!eof) nchars++;
                    } else {
                        if (!eof) { ungetc(c2, f); nchars--; }
                    }
                    /* c stays '0', scanned below */
                }
                {
                    unsigned long vv = 0;
                    int nn = 0;
                    for (;;) {
                        int d = -1;
                        if (w == 0) break;
                        if (c == EOF) break;
                        if (c >= '0' && c <= '9') d = c - '0';
                        else if (c >= 'a' && c <= 'z') d = c - 'a' + 10;
                        else if (c >= 'A' && c <= 'Z') d = c - 'A' + 10;
                        if (d < 0 || d >= base) { ungetc(c, f); nchars--; break; }
                        vv = vv * (unsigned long)base + (unsigned long)d;
                        nn++;
                        if (w > 0) w--;
                        if (w == 0) break;
                        c = scan_getc(f, &eof);
                        if (!eof) nchars++;
                        else break;
                    }
                    v = vv; nd = nn;
                }
                if (nd == 0) break;
                if (!suppress) {
                    if (*fmt == 'u' || *fmt == 'o' || *fmt == 'x' || *fmt == 'X') {
                        unsigned *up = va_arg(ap, unsigned *);
                        *up = (unsigned)v;
                    } else if (islong) {
                        long *lp = va_arg(ap, long *);
                        *lp = neg ? -(long)v : (long)v;
                    } else if (isshort) {
                        short *hp = va_arg(ap, short *);
                        *hp = (short)(neg ? -(long)v : (long)v);
                    } else {
                        int *ip = va_arg(ap, int *);
                        *ip = (int)(neg ? -(long)v : (long)v);
                    }
                    assigned++;
                }
                fmt++;
                continue;
            } else if (*fmt == 'e' || *fmt == 'f' || *fmt == 'g' ||
                       *fmt == 'E' || *fmt == 'F' || *fmt == 'G' ||
                       *fmt == 'a' || *fmt == 'A') {
                /* parse decimal float text, convert via strtod-like logic */
                char tmp[128];
                int n = 0, c;
                do { c = scan_getc(f, &eof); if (!eof) nchars++; } while (!eof && scan_isspace(c));
                if (eof) break;
                while (!eof && n < 120) {
                    if ((c >= '0' && c <= '9') || c == '+' || c == '-' ||
                        c == '.' || c == 'e' || c == 'E') {
                        tmp[n++] = (char)c;
                    } else break;
                    c = scan_getc(f, &eof);
                    if (!eof) nchars++;
                }
                if (!eof) { ungetc(c, f); nchars--; }
                tmp[n] = '\0';
                if (n == 0) break;
                if (!suppress) {
                    double dv = strtod(tmp, 0);
                    if (islong || *fmt == 'l') {
                        /* %lf already consumed? (l handled above) */
                    }
                    if (*fmt == 'f' || *fmt == 'e' || *fmt == 'g' ||
                        *fmt == 'E' || *fmt == 'G' || *fmt == 'a' || *fmt == 'A') {
                        /* length already parsed; default float unless l */
                        if (islong) {
                            double *dp = va_arg(ap, double *);
                            *dp = dv;
                        } else {
                            float *fp = va_arg(ap, float *);
                            *fp = (float)dv;
                        }
                    }
                    assigned++;
                }
                fmt++;
                continue;
            } else {
                break;
            }
        }
    }
    if (eof && assigned == 0) return EOF;
    return assigned;
}

int fscanf(FILE *stream, const char *format, ...)
{
    va_list ap;
    int r;
    va_start(ap, format);
    r = vfscanf_impl(stream, format, ap);
    va_end(ap);
    return r;
}

int sscanf(const char *str, const char *format, ...)
{
    /* implement over memory by a temp FILE-like reader */
    extern int vsscanf_impl(const char *s, const char *format, va_list ap);
    va_list ap;
    int r;
    va_start(ap, format);
    r = vsscanf_impl(str, format, ap);
    va_end(ap);
    return r;
}

/* sscanf shares logic via a memory stream */
typedef struct { const char *p; int eof; } memrd;

static int mem_getc(memrd *m)
{
    if (*m->p == '\0') { m->eof = 1; return EOF; }
    return (unsigned char)*m->p++;
}

static void mem_ungetc(memrd *m)
{
    if (m->p) { m->p--; m->eof = 0; }
}

int vsscanf_impl(const char *s, const char *format, va_list ap)
{
    memrd m;
    int assigned = 0, nchars = 0;
    m.p = s; m.eof = 0;
    while (*format && !m.eof) {
        if (scan_isspace((unsigned char)*format)) {
            int c;
            format++;
            while (scan_isspace((unsigned char)*format)) format++;
            do { c = mem_getc(&m); nchars++; } while (!m.eof && scan_isspace(c));
            if (!m.eof) { mem_ungetc(&m); nchars--; }
            continue;
        }
        if (*format != '%') {
            int c = mem_getc(&m);
            nchars++;
            if (m.eof || c != (unsigned char)*format) break;
            format++;
            continue;
        }
        format++;
        {
            int suppress = 0, width = -1, islong = 0, isshort = 0;
            if (*format == '*') { suppress = 1; format++; }
            if (*format >= '0' && *format <= '9') {
                width = 0;
                while (*format >= '0' && *format <= '9') width = width * 10 + (*format++ - '0');
            }
            if (*format == 'h') { isshort = 1; format++; if (*format == 'h') format++; }
            else if (*format == 'l') { format++; islong = 1; if (*format == 'l') format++; }
            else if (*format == 'j' || *format == 'z' || *format == 't' || *format == 'L') format++;
            if (*format == '%') {
                int c = mem_getc(&m);
                nchars++;
                if (m.eof || c != '%') break;
                format++;
                continue;
            } else if (*format == 'n') {
                int *ip = suppress ? 0 : va_arg(ap, int *);
                if (ip) *ip = nchars;
                format++;
                continue;
            } else if (*format == 'c') {
                char *sp = suppress ? 0 : va_arg(ap, char *);
                int n = width < 0 ? 1 : width, i;
                for (i = 0; i < n; i++) {
                    int c = mem_getc(&m);
                    if (m.eof) break;
                    nchars++;
                    if (sp) sp[i] = (char)c;
                }
                if (m.eof && (width < 0 || nchars == 0)) break;
                if (!suppress && n > 0) assigned++;
                format++;
                continue;
            } else if (*format == 's') {
                char *sp = suppress ? 0 : va_arg(ap, char *);
                int c, n = 0;
                do { c = mem_getc(&m); if (!m.eof) nchars++; } while (!m.eof && scan_isspace(c));
                if (m.eof) break;
                for (;;) {
                    if (width >= 0 && n >= width) { mem_ungetc(&m); nchars--; break; }
                    if (scan_isspace(c)) { mem_ungetc(&m); nchars--; break; }
                    if (sp) sp[n] = (char)c;
                    n++;
                    c = mem_getc(&m);
                    if (m.eof) break;
                    nchars++;
                }
                if (n == 0) break;
                if (sp) sp[n] = '\0';
                if (!suppress) assigned++;
                format++;
                continue;
            } else if (*format == '[') {
                char *sp = suppress ? 0 : va_arg(ap, char *);
                char set[256];
                int negate = 0, n = 0, c;
                format++;
                memset(set, 0, sizeof(set));
                if (*format == '^') { negate = 1; format++; }
                if (*format == ']') { set[']'] = 1; format++; }
                while (*format && *format != ']') {
                    if (format[1] == '-' && format[2] && format[2] != ']') {
                        int a = (unsigned char)format[0], b = (unsigned char)format[2], k;
                        for (k = a; k <= b; k++) set[k] = 1;
                        format += 3;
                    } else {
                        set[(unsigned char)*format] = 1;
                        format++;
                    }
                }
                if (*format == ']') format++;
                c = mem_getc(&m);
                if (!m.eof) nchars++;
                for (;;) {
                    int hit;
                    if (m.eof) break;
                    hit = set[c] ? 1 : 0;
                    if (negate) hit = !hit;
                    if (!hit) { mem_ungetc(&m); nchars--; break; }
                    if (width >= 0 && n >= width) { mem_ungetc(&m); nchars--; break; }
                    if (sp) sp[n] = (char)c;
